head.script:
// https://inswave01.atlassian.net/browse/WAEA-1126



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
// ※ 엔진 결함(2026-08-13 실측) : mapchart 는 setSize 시 컴포넌트 div 와 getSize() 만 변경되고
//    내부 SVG(#{id}_svg) 의 width/height attribute 는 생성 시점(300x300) 그대로 고정되어 지도가 리사이즈되지 않는다.
//    (mapchart.js createMap() 이 생성 시 1회만 attr 설정, viewBox 없음 / setSize 오버라이드 없음)
//    fw* 차트 계열과 동일 결함이며, 반환값(getSize)만 보면 정상으로 보이므로 SVG attribute 로 확인해야 한다.
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createBasicMapChart();
}
